package com.restaurant.billing.api;
import com.restaurant.platform.api.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/outlets/{outletId}/invoices") public class InvoiceSearchController {
 private final JdbcTemplate jdbc; public InvoiceSearchController(JdbcTemplate j){jdbc=j;}
 @GetMapping public Map<String,Object> list(@PathVariable UUID outletId,@RequestParam(required=false) String q,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){var p=TenantContext.require();if(p.isGuest()||p.outletIds()==null||!p.outletIds().contains(outletId))throw ApiException.forbidden("OUTLET_ACCESS","You do not have access to this outlet");int s=Math.max(1,Math.min(size,100)), offset=Math.max(0,page)*s;String search=q==null?"":q.trim();String state=status==null?"":status.trim().toUpperCase();var rows=jdbc.query("select i.id,i.invoice_number,i.status,i.total_paise,i.created_at,o.table_id from invoices i join orders o on o.id=i.order_id where i.tenant_id=? and i.outlet_id=? and (?='' or i.invoice_number ilike '%'||?||'%') and (?='' or i.status=?) order by i.created_at desc limit ? offset ?",(r,n)->Map.<String,Object>of("id",r.getObject(1,UUID.class),"invoiceNumber",r.getString(2)==null?r.getObject(1,UUID.class).toString():r.getString(2),"status",r.getString(3),"totalPaise",r.getLong(4),"createdAt",r.getTimestamp(5).toInstant().toString(),"tableId",String.valueOf(r.getObject(6))),p.tenantId(),outletId,search,search,state,state,s,offset);Long total=jdbc.queryForObject("select count(*) from invoices where tenant_id=? and outlet_id=? and (?='' or invoice_number ilike '%'||?||'%') and (?='' or status=?)",Long.class,p.tenantId(),outletId,search,search,state,state);return Map.of("content",rows,"page",Math.max(0,page),"size",s,"totalElements",total==null?0:total);}
 @GetMapping("/{invoiceId}") public Map<String,Object> detail(@PathVariable UUID outletId,@PathVariable UUID invoiceId){var p=TenantContext.require();if(p.isGuest()||p.outletIds()==null||!p.outletIds().contains(outletId))throw ApiException.forbidden("OUTLET_ACCESS","You do not have access to this outlet");var h=jdbc.query("select invoice_number,status,total_paise,created_at from invoices where id=? and tenant_id=? and outlet_id=?",(r,n)->Map.of("invoiceNumber",r.getString(1),"status",r.getString(2),"totalPaise",r.getLong(3),"createdAt",r.getTimestamp(4).toInstant().toString()),invoiceId,p.tenantId(),outletId).stream().findFirst().orElseThrow(()->ApiException.notFound("INVOICE","Invoice not found"));var lines=jdbc.query("select name,qty,line_paise from invoice_lines where invoice_id=?",(r,n)->Map.of("name",r.getString(1),"qty",r.getBigDecimal(2).toPlainString(),"linePaise",r.getLong(3)),invoiceId);var payments=jdbc.query("select method,amount_paise,status,created_at from payments where invoice_id=?",(r,n)->Map.of("method",r.getString(1),"amountPaise",r.getLong(2),"status",r.getString(3),"createdAt",r.getTimestamp(4).toInstant().toString()),invoiceId);return Map.of("invoice",h,"lines",lines,"payments",payments);}}
